-- 150K rows of PBGC pension insurance statistics -- claims, payments, and program finances by year.
-- Auto-generated by scripts/gen_evidence_pages.py: 149,771 rows > 100k, so this is a BOUNDED pre-aggregate (parquet-safe by construction), not select *.
-- grouped on year-like text/number column DATA_YEAR (NOT date-cast -- avoids the 8-digit epoch trap); LIMIT bounds it.
select "DATA_YEAR" as year, count(*) as records
from THE_LIBRARY.ECONOMY.PENSION_INSURANCE_STATS
group by 1
order by 1
limit 1000
